19	/* A colour pixmap starts black; a bitmap's bits are left for the caller. */
20	static struct XshimPixmap *pixmap_new(int w, int h, int depth) {
21	  struct XshimPixmap *pm = (struct XshimPixmap *)calloc(1, sizeof(*pm));
22	  if (!pm) return NULL;
23	  pm->w = w;
24	  pm->h = h;
25	  pm->depth = depth;
26	  pm->stride = (w + 7) / 8;
27	  const int ok = depth == 1
28	                     ? (pm->bits = (uint8_t *)malloc((size_t)pm->stride * (size_t)h)) != NULL
29	                     : canvas_init(&pm->canvas, w, h, malloc) == 0;
30	  if (!ok) {
31	    pixmap_free(pm);
32	    return NULL;
33	  }
34	  return pm;
35	}
