37	Canvas *xshim_target(Display *dpy, Drawable d) {
38	  if (d == XSHIM_WINDOW) return dpy->canvas;
39	  struct XshimPixmap *pm = pixmap_of(d);
40	  return pm && pm->depth == 16 ? &pm->canvas : NULL;
41	}
