43	static void track(Display *dpy, struct XshimPixmap *pm) {
44	  pm->prev = NULL;
45	  pm->next = dpy->pixmaps;
46	  if (dpy->pixmaps) dpy->pixmaps->prev = pm;
47	  dpy->pixmaps = pm;
48	}
49	
50	static void untrack(Display *dpy, struct XshimPixmap *pm) {
51	  if (pm->prev)
52	    pm->prev->next = pm->next;
53	  else
54	    dpy->pixmaps = pm->next;
55	  if (pm->next) pm->next->prev = pm->prev;
56	}
57	
58	static void (*g_release_hook)(Display *dpy);
59	
60	void xshim_set_release_hook(void (*hook)(Display *dpy)) { g_release_hook = hook; }
61	
62	void xshim_release_pixmaps(Display *dpy) {
63	  /* The display outlives a hack: the window background it set must not
64	   * become the next hack's XClearWindow colour. */
65	  dpy->window_background = 0;
66	  while (dpy->pixmaps) {
67	    struct XshimPixmap *pm = dpy->pixmaps;
68	    untrack(dpy, pm);
69	    pixmap_free(pm);
70	  }
71	  if (g_release_hook) {
72	    void (*hook)(Display *) = g_release_hook;
73	    g_release_hook = NULL;
74	    hook(dpy);
75	  }
76	}
