78	static int bit_at(const struct XshimPixmap *pm, int x, int y) {
79	  return (pm->bits[y * pm->stride + x / 8] >> (7 - x % 8)) & 1;
80	}
81	
82	static unsigned le16(const unsigned char *p) { return p[0] | (p[1] << 8); }
83	
84	Pixmap image_data_to_pixmap(Display *dpy, Window win, const unsigned char *data,
85	                            unsigned long size, int *width_ret,
86	                            int *height_ret, Pixmap *mask_ret) {
87	  (void)win;
88	  if (width_ret) *width_ret = 0;
89	  if (height_ret) *height_ret = 0;
90	  if (mask_ret) *mask_ret = None;
91	  if (size < 8 || memcmp(data, "565M", 4) != 0) return None;
92	
93	  const unsigned w = le16(data + 4), h = le16(data + 6);
94	  const uint64_t pixel_bytes = (uint64_t)w * h * 2;
95	  const uint64_t mask_bytes = (uint64_t)((w + 7) / 8) * h;
96	  if (w == 0 || h == 0 || size != 8 + pixel_bytes + mask_bytes) return None;
97	
98	  struct XshimPixmap *colour = pixmap_new((int)w, (int)h, 16);
99	  struct XshimPixmap *mask = mask_ret ? pixmap_new((int)w, (int)h, 1) : NULL;
100	  if (!colour || (mask_ret && !mask)) {
101	    pixmap_free(colour);
102	    pixmap_free(mask);
103	    return None;
104	  }
105	  for (unsigned i = 0; i < w * h; i++)
106	    colour->canvas.px[i] = px_swap((uint16_t)le16(data + 8 + 2 * i));
107	  if (mask) memcpy(mask->bits, data + 8 + pixel_bytes, (size_t)mask_bytes);
108	
109	  track(dpy, colour);
110	  if (mask) track(dpy, mask);
111	  if (width_ret) *width_ret = (int)w;
112	  if (height_ret) *height_ret = (int)h;
113	  if (mask_ret) *mask_ret = (Pixmap)(uintptr_t)mask;
114	  return (Pixmap)(uintptr_t)colour;
115	}
