178	static int clipped_out(const GC gc, int64_t x, int64_t y) {
179	  if (!gc->clip) return 0;
180	  const int64_t mx = x - gc->clip_x, my = y - gc->clip_y;
181	  if (mx < 0 || my < 0 || mx >= gc->clip->w || my >= gc->clip->h) return 1;
182	  return !bit_at(gc->clip, (int)mx, (int)my);
