192	Pixmap XCreatePixmap(Display *dpy, Drawable d, unsigned int w, unsigned int h,
193	                     unsigned int depth) {
194	  (void)d;
195	  if (w == 0 || h == 0 || (uint64_t)w * h > MAX_PIXMAP_PIXELS) return None;
196	  struct XshimPixmap *pm = pixmap_new((int)w, (int)h, depth == 1 ? 1 : 16);
197	  if (!pm) return None;
198	  track(dpy, pm);
199	  if (pm->bits) memset(pm->bits, 0, (size_t)pm->stride * (size_t)pm->h);
200	  return (Pixmap)(uintptr_t)pm;
201	}
