203	static void set_bit(struct XshimPixmap *pm, int x, int y, int on) {
204	  uint8_t *byte = &pm->bits[y * pm->stride + x / 8];
205	  const uint8_t mask = (uint8_t)(0x80 >> (x % 8));
206	  *byte = on ? (uint8_t)(*byte | mask) : (uint8_t)(*byte & ~mask);
207	}
