209	Pixmap XCreatePixmapFromBitmapData(Display *dpy, Drawable d, char *data,
210	                                   unsigned int w, unsigned int h,
211	                                   unsigned long fg, unsigned long bg,
212	                                   unsigned int depth) {
213	  Pixmap p = XCreatePixmap(dpy, d, w, h, depth);
214	  struct XshimPixmap *pm = pixmap_of(p);
215	  if (!pm || !data) return p;
216	  const size_t row_bytes = ((size_t)w + 7) / 8;
217	  for (unsigned y = 0; y < h; y++)
218	    for (unsigned x = 0; x < w; x++) {
219	      const int on = ((unsigned char)data[y * row_bytes + x / 8] >> (x % 8)) & 1;
220	      if (pm->depth == 1)
221	        set_bit(pm, (int)x, (int)y, on);
222	      else
223	        pm->canvas.px[y * w + x] = (uint16_t)(on ? fg : bg);
224	    }
225	  return p;
226	}
