    canvas_fill_ellipse(c, x, y, w > 0x7FFFFFFF ? 0x7FFFFFFF : (int)w,
                        h > 0x7FFFFFFF ? 0x7FFFFFFF : (int)h,
                        (uint16_t)gc->foreground);

