703	{
704	  int i;
705	  for (i=0;i<p->ec->size;i++) {
706	    if (p->ec->array[i][CLOCKWISE]==0) {
707	      *e=p->graph->edges->elements[i];
708	      *d=CLOCKWISE;
709	      return 1;
710	    }
711	    else if (p->ec->array[i][ANTICLOCKWISE]==0) {
712	      *e=p->graph->edges->elements[i];
713	      *d=ANTICLOCKWISE;
714	      return 1;
715	    }
716	  }
717	  return 0;
718	}
